/* Visual layer: progressive enhancement; all existing product actions are retained. */
function visualChart(){const values=insightRange==='month'?[110,81,53]:[42,28,19],max=Math.max(...values);return `<section class="visual-report surface"><div><span class="tag blue">دادهٔ نمونه</span><h3>کدام محتوا گفتگو ساخت؟</h3><p>تعداد شروع گفتگو در بازهٔ انتخاب‌شده</p></div><div class="visual-bars">${values.map((v,i)=>`<div class="visual-bar-row"><span>${['راهنمای هدیه','پشت صحنه','پرسش‌های ارسال'][i]}</span><div class="visual-bar-track"><i style="width:${v/max*100}%;--bar:${['#6A5ACD','#14B8A6','#FF8A5B'][i]}"></i></div><b>${fa(v)}</b></div>`).join('')}</div></section>`}
function commandDashboard(){const open=messagesState.filter(m=>m.state!=='done').length,review=posts.filter(p=>p.workflow==='review').length,scheduled=posts.filter(p=>p.workflow==='scheduled').length,drafts=posts.filter(p=>p.draft).length,total=posts.length,ready=posts.filter(p=>['approved','scheduled'].includes(p.workflow)).length,ratio=total?Math.round(ready/total*100):0;return titleV3('نمای کلی','نبض فضای کار شما؛ از ایده تا ارتباط و انتشار.',button('ساخت محتوا','data-action="post"',true,'plus'))+`<div class="command-grid"><section class="command-mission"><div class="command-kicker"><span class="live-dot"></span> اتاق فرمان برند شما</div><h2>امروز، یک قدم<br><em>اثرگذارتر.</em></h2><p>همهٔ بازوهای کسب‌وکارت، در یک مسیر.</p><div class="mission-actions"><button data-page="inbox">${icon('inbox')}<b>${fa(open)}</b><span>گفتگوی باز</span>←</button><button data-page="studio">${icon('camera')}<b>${fa(review)}</b><span>در انتظار بازبینی</span>←</button></div><div class="mission-mascot" aria-hidden="true">${octopusIcon()}</div><small>وضعیت ثبت‌شده در همین مرورگر</small></section><section class="command-orbit"><span class="command-label">آمادگی محتوا</span><div class="content-dial" style="--progress:${ratio}%"><div><b>${fa(ratio)}٪</b><small>تأیید یا زمان‌بندی‌شده</small></div></div><div class="dial-legend"><span><i></i> آماده <b>${fa(ready)}</b></span><span><i></i> سایر محتوا <b>${fa(total-ready)}</b></span></div><button class="text-link" data-page="studio">مدیریت ${fa(total)} محتوا ←</button></section><section class="command-launch"><span class="command-label">میز خلاقیت</span><h3>از کجا شروع کنیم؟</h3><div class="launch-options"><button data-create-format="image">${icon('camera')}<b>پست تصویری</b><small>روایت در یک قاب</small></button><button data-create-format="text">${icon('book')}<b>محتوای متنی</b><small>یک حرف تازه</small></button><button data-page="growth">${octopusIcon()}<b>ایده با هشتیوا</b><small>الهام از گفتگوها</small></button></div></section><section class="command-queue surface"><div class="command-section-title"><div><span class="command-label">صف تولید</span><h3>ایده‌های در جریان</h3></div><button class="text-link" data-page="studio">استودیو ←</button></div>${dailyPosts()||'<p class="muted">اولین محتوایت را بساز.</p>'}<div class="queue-counts"><span>${fa(drafts)} پیش‌نویس</span><span>${fa(review)} بازبینی</span><span>${fa(scheduled)} زمان‌بندی</span></div></section><section class="command-copilot"><div>${octopusIcon()}<span>همراه هشتیوا<small>پیشنهاد آماده · بدون مدل زنده</small></span></div><h3>سؤال امروز مشتری،<br>محتوای فردای تو.</h3><p>از یک گفتگوی مخاطب، پیش‌نویس آموزشی بساز.</p><button data-page="growth">کشف پیشنهادها ${icon('arrow')}</button></section><section class="command-channels surface"><div class="command-section-title"><h3>بازوهای ارتباطی</h3><button class="text-link" data-page="channels">مدیریت ←</button></div><div>${accounts.map(a=>`<button class="command-account" data-page="channels">${social(a.network)}<span><b dir="auto">${safe(a.name)}</b><small>${channelState[a.id]==='disconnected'?'قطع‌شده · شبیه‌سازی':'حساب نمونه'}</small></span><i class="${channelState[a.id]==='disconnected'?'offline':''}"></i></button>`).join('')||'<p>یک حساب نمونه اضافه کنید.</p>'}</div></section></div>`}
function studioDesk(){return `<section class="studio-desk"><div class="desk-title"><span>CREATIVE STUDIO</span><h2>قالب بعدی‌ات را انتخاب کن</h2><small>هر قالب، شروع یک داستان تازه</small></div><button data-create-format="image"><span class="format-illustration image-frame">${icon('camera')}<i></i></span><b>قاب تصویری</b><small>پست و محتوای بصری ←</small></button><button data-create-format="text"><span class="format-illustration text-frame"><i></i><i></i><i></i></span><b>روایت متنی</b><small>برای تلگرام و شبکه‌ها ←</small></button><button data-page="growth"><span class="format-illustration idea-frame">${octopusIcon()}</span><b>شروع با یک ایده</b><small>از پیشنهادهای هشتیوا ←</small></button></section>`}
function inboxPulse(){return `<div class="inbox-pulse">${[['all','همهٔ گفتگوها',messagesState.length,'inbox'],['open','باز',messagesState.filter(m=>m.state==='open').length,'clock'],['human','ارجاع به تیم',messagesState.filter(m=>m.state==='human').length,'users'],['done','بسته‌شده',messagesState.filter(m=>m.state==='done').length,'check']].map(([v,t,n,ic])=>`<button data-inbox-filter="${v}" class="${inboxFilter===v?'selected':''}">${icon(ic)}<span>${t}</span><b>${fa(n)}</b></button>`).join('')}</div>`}
function libraryDesk(){return `<div class="knowledge-desk"><div class="knowledge-books" aria-hidden="true"><i>برند</i><i>محصول</i><i>پاسخ</i>${octopusIcon()}</div><div><span class="command-label">کتابخانهٔ دستیار</span><h2>شناخت بیشتر، پاسخ روشن‌تر.</h2><p>${fa(knowledge.length)} منبع برای صدای برند شما</p></div><button class="btn primary" data-new-knowledge>${icon('plus')} منبع تازه</button></div>`}
const beforeVisualRender=render;
render=function(page='dashboard'){beforeVisualRender(page);main.dataset.view=current;if(current==='dashboard')main.innerHTML=commandDashboard();if(current==='studio')main.querySelector('.section-toolbar')?.insertAdjacentHTML('beforebegin',studioDesk());if(current==='inbox')main.querySelector('.inbox-workspace')?.insertAdjacentHTML('beforebegin',inboxPulse());if(current==='knowledge')main.querySelector('.knowledge-layout')?.insertAdjacentHTML('beforebegin',libraryDesk());if(current==='analytics')main.querySelector('.overview-metrics')?.insertAdjacentHTML('afterend',visualChart());if(current==='automations')document.querySelectorAll('.flow-route').forEach(el=>el.querySelectorAll('span').forEach((node,i)=>node.insertAdjacentHTML('afterbegin',icon(['inbox','spark','users'][i%3]))));if(current==='growth')document.querySelectorAll('.opportunity').forEach((el,i)=>el.insertAdjacentHTML('afterbegin',`<div class="experiment-mark" aria-hidden="true">${icon(['camera','inbox','chart'][i%3])}<span>آزمایش ${fa(i+1)}</span></div>`));};
const themeControl=document.querySelector('#theme');
function updateThemeControl(){const dark=document.body.classList.contains('dark');themeControl.innerHTML=dark?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/></svg>':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M20.5 14A9 9 0 0 1 10 3a9 9 0 1 0 10.5 11Z"/><path d="M17 3v5m-2.5-2.5h5"/></svg>';themeControl.setAttribute('aria-label',dark?'فعال‌کردن حالت روشن':'فعال‌کردن حالت تیره');themeControl.setAttribute('title',dark?'حالت روشن':'حالت تیره');themeControl.setAttribute('aria-pressed',String(dark));}
themeControl.onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('hashtiva-theme',document.body.classList.contains('dark')?'dark':'light');updateThemeControl()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-create-format]');if(!b)return;openComposer(-1,{title:'',caption:'',kind:b.dataset.createFormat==='image'?'پست تصویری':'متن',networks:b.dataset.createFormat==='image'?['instagram']:['telegram']})});
updateThemeControl();render(location.hash.slice(1)||'dashboard');
